class AlertInstrumentationTest{@get:Rule val compose=createComposeRule();@Test fun deterministicAlertAndNotificationScenario(){val ma=AlertEvent("ma","1234","測試股票","2026-08-11T10:00:00Z","2026-08-11","MA_CROSS_ABOVE","11","10","MA20","1234 收盤由 MA20 下方突破至上方","FINAL",null);val target=AlertEvent("target","1234","測試股票","2026-08-11T10:01:00Z","2026-08-11","PRICE_TARGET","12","12","TARGET_PRICE","1234 收盤突破設定目標價","FINAL","2026-08-11T10:02:00Z");compose.setContent{NotificationCenterScreen(AlertUiState.Success(AlertDashboard(emptyList(),listOf(ma,target))))};compose.onNodeWithText("未讀 1").assertIsDisplayed();compose.onNodeWithText(ma.message).assertIsDisplayed();compose.onNodeWithText(target.message).assertIsDisplayed();compose.onAllNodesWithText("標記已讀").assertCountEquals(2)}}
